static unsigned readcsr(void) { unsigned x; __asm__ volatile("stmxcsr %0":"=m"(x)); return x; }
static void writecsr(unsigned x) { __asm__ volatile("ldmxcsr %0"::"m"(x)); }
static unsigned get16(const unsigned char*p) { return p[0]|(unsigned)p[1]<<8; }
static void scalar(const struct Case*c,const unsigned char*a,const unsigned char*b,unsigned char*out) {
  if(c->kind==0) {
    unsigned z=0,cy=0;
    if(c->lane==1) { for(unsigned j=0;j<c->width;j++){z|=a[j]&b[j];cy|=(unsigned char)~a[j]&b[j];} }
    else for(unsigned j=c->lane-1;j<c->width;j+=c->lane){z|=(a[j]&b[j])&128;cy|=((unsigned char)~a[j]&b[j])&128;}
    int v=c->control==0?z==0:c->control==1?cy==0:z!=0&&cy!=0; memcpy(out,&v,4);
  } else if(c->kind==1) {
    unsigned best=65535,index=0; for(unsigned j=0;j<8;j++){unsigned v=get16(a+j*2);if(v<best){best=v;index=j;}}
    memset(out,0,16);out[0]=(unsigned char)best;out[1]=(unsigned char)(best>>8);out[2]=(unsigned char)index;
  } else if(c->kind==2) {
    for(unsigned half=0;half<c->width/16;half++) {
      unsigned ctrl=c->control>>(half*3),aa=(ctrl&4),bb=(ctrl&3)*4;
      for(unsigned j=0;j<8;j++){unsigned sum=0;for(unsigned k=0;k<4;k++){unsigned x=a[half*16+aa+j+k],y=b[half*16+bb+k];sum+=x>y?x-y:y-x;}out[half*16+j*2]=(unsigned char)sum;out[half*16+j*2+1]=(unsigned char)(sum>>8);}
    }
  }
}
int main(void) {
  unsigned saved=readcsr(); unsigned char a[48],b[48],actual[48],reference[48],expected[48];
  for(unsigned ci=0;ci<sizeof(cases)/sizeof(cases[0]);ci++) {
    const struct Case*c=&cases[ci];
    for(unsigned pattern=0;pattern<70;pattern++) {
      for(unsigned j=0;j<48;j++){a[j]=(unsigned char)(j*73+pattern*167);b[j]=(unsigned char)(j*197+pattern*79);}
      if(pattern<4){memset(a,pattern&1?255:0,48);memset(b,pattern&2?255:0,48);}
      if(pattern==4){memset(a,0,48);memset(b,128,48);}
      if(pattern==5){memset(a,128,48);memset(b,1,48);}
      if(pattern==6){memset(a,1,48);memset(b,128,48);}
      if(pattern==7){memset(a,128,48);memset(b,128,48);}
      for(unsigned rc=0;rc<4;rc++) {
        unsigned seed=0x1f80u|(rc<<13)|(pattern&1?0x21u:0u);
        memset(actual,0xa5,48);memset(reference,0xa5,48);memset(expected,0xa5,48);
        writecsr(seed);c->actual(actual+3,a+1,b+1);unsigned af=readcsr();
        writecsr(seed);c->reference(reference+3,a+1,b+1);unsigned rf=readcsr();
        if(memcmp(actual,reference,48)||af!=rf){writecsr(saved);fprintf(stderr,"%s case %u pattern %u rc %u csr %x/%x\n",c->name,ci,pattern,rc,af,rf);return 1;}
        if(c->kind!=3){scalar(c,a+1,b+1,expected+3);if(memcmp(actual,expected,48)){writecsr(saved);fprintf(stderr,"scalar %s case %u pattern %u\n",c->name,ci,pattern);return 1;}}
        unsigned char alias[48];memcpy(alias,a,48);writecsr(seed);c->actual(alias+1,alias+1,b+1);af=readcsr();
        if(memcmp(alias+1,reference+3,c->out)||af!=rf){writecsr(saved);fprintf(stderr,"alias %s case %u pattern %u\n",c->name,ci,pattern);return 1;}
      }
    }
  }
  writecsr(saved);puts("PASS queries, dot products, minimum-position and multiple SAD");return 0;
}
